import{_ as a,o as t,c as i,ae as n}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"Bill Refunds","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/10-bill-refund-guide.md","filePath":"v1/en/guide/10-bill-refund-guide.md"}'),r={name:"v1/en/guide/10-bill-refund-guide.md"};function l(o,e,d,s,u,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="bill-refunds" tabindex="-1">Bill Refunds <a class="header-anchor" href="#bill-refunds" aria-label="Permalink to &quot;Bill Refunds&quot;">​</a></h1><h2 id="_1-what-this-feature-is" tabindex="-1">1. What this feature is <a class="header-anchor" href="#_1-what-this-feature-is" aria-label="Permalink to &quot;1. What this feature is&quot;">​</a></h2><p>Refunds are used to record the cash flow when a bill is refunded, and to automatically offset its impact in statistics.</p><p>Koala does this by creating an additional “refund record” with a negative amount based on the original bill:</p><ul><li>If the original bill is an expense, the refund record is also an expense, but with a negative amount to offset the original expense.</li><li>If the original bill is an income, the refund record is also an income, but with a negative amount to offset the original income.</li></ul><p>Refund records are automatically tagged with <strong>Refund</strong> for easier filtering and review.</p><h2 id="_2-when-to-use-it" tabindex="-1">2. When to use it <a class="header-anchor" href="#_2-when-to-use-it" aria-label="Permalink to &quot;2. When to use it&quot;">​</a></h2><ul><li>Shopping refunds / returns</li><li>Partial refunds</li><li>Income reversals (for example, a transfer being revoked or a payment being returned)</li></ul><h2 id="_3-how-to-use-it" tabindex="-1">3. How to use it <a class="header-anchor" href="#_3-how-to-use-it" aria-label="Permalink to &quot;3. How to use it&quot;">​</a></h2><ol><li>Open the bill list and find the bill you want to refund</li><li>Swipe left on the bill and select <strong>Refund</strong></li><li>On the refund page, set: <ul><li>Amount: defaults to the original amount; you can change it for a partial refund</li><li>Date: defaults to today; change it to the actual refund date if needed</li><li>Tags: inherits the original bill’s tags and automatically adds the <strong>Refund</strong> tag</li><li>Note: optional, for additional context</li></ul></li><li>Tap <strong>Confirm/Done</strong> to save</li></ol><p>After saving, a new refund record appears in the list to offset the corresponding amount impact.</p><h2 id="_4-rules-and-notes" tabindex="-1">4. Rules and notes <a class="header-anchor" href="#_4-rules-and-notes" aria-label="Permalink to &quot;4. Rules and notes&quot;">​</a></h2><ul><li>Enter the amount that was actually refunded; you don’t need to type a minus sign.</li><li>Both expense refunds and income refunds are recorded as negative amounts, so they automatically offset totals.</li><li>Multiple refunds are supported: if the same bill is refunded in multiple parts, you can repeat the process and create one refund record per refund.</li><li>If you delete a refund record, its offset effect will also be removed (statistics return to the pre-refund state).</li></ul><h2 id="_5-faq" tabindex="-1">5. FAQ <a class="header-anchor" href="#_5-faq" aria-label="Permalink to &quot;5. FAQ&quot;">​</a></h2><h3 id="q1-how-do-i-record-a-partial-refund" tabindex="-1">Q1: How do I record a partial refund? <a class="header-anchor" href="#q1-how-do-i-record-a-partial-refund" aria-label="Permalink to &quot;Q1: How do I record a partial refund?&quot;">​</a></h3><p>Change the amount on the refund page to the refunded amount. You can also refund multiple times and enter each refunded amount separately.</p><h3 id="q2-does-a-refund-change-the-original-bill" tabindex="-1">Q2: Does a refund change the original bill? <a class="header-anchor" href="#q2-does-a-refund-change-the-original-bill" aria-label="Permalink to &quot;Q2: Does a refund change the original bill?&quot;">​</a></h3><p>The original bill amount is not modified. A refund is implemented by adding a separate refund record. This preserves the original spending record while keeping statistics explainable and traceable.</p><h3 id="q3-how-can-i-quickly-find-all-refunds" tabindex="-1">Q3: How can I quickly find all refunds? <a class="header-anchor" href="#q3-how-can-i-quickly-find-all-refunds" aria-label="Permalink to &quot;Q3: How can I quickly find all refunds?&quot;">​</a></h3><p>Refund records are automatically tagged with <strong>Refund</strong>, so you can filter/search by that tag.</p>',20)])])}const p=a(r,[["render",l]]);export{c as __pageData,p as default};
